// Keep the download independent of the hosting service's PDF route.
const resumeBase64 = "";
document.querySelectorAll('[data-resume-download]').forEach(link => {
 link.addEventListener('click', event => {
  try {
   const bytes=Uint8Array.from(atob(resumeBase64),c=>c.charCodeAt(0));
   const url=URL.createObjectURL(new Blob([bytes],{type:'application/pdf'}));
   const download=document.createElement('a');
   download.href=url; download.download='Sanchita-Senapati-Resume.pdf';
   document.body.appendChild(download); download.click(); download.remove();
   setTimeout(()=>URL.revokeObjectURL(url),60000);
   event.preventDefault();
  } catch(error) { /* The original PDF link remains the fallback. */ }
 });
});
